const product = $('Pick Random Product').first().json;
const geminiRes = $input.all()[0].json;
const postText = geminiRes.candidates?.[0]?.content?.parts?.[0]?.text || "Descubre nuestro nuevo producto en shongyi.com/bazar?p=" + product.id;
return [{
  json: {
    message: postText,
    link: "https://shongyi.com/bazar?p=" + product.id,
    imageUrl: product.imageUrl
  }
}];

const item = $input.all()[0];
const textContent = `IMAGEN:\n${item.json.imageUrl}\n\nTEXTO DEL POST:\n${item.json.message}`;

item.binary = {
  data: {
    data: Buffer.from(textContent).toString('base64'),
    mimeType: 'text/plain',
    fileName: 'post_para_facebook.txt'
  }
};
return [item];
